    for k in ("CLAUDE_CONFIG_DIR", "CLAUDE_CODE_PROJECT_DIR_NAME",
              "CLAUDE_CODE_DISABLE_AUTO_MEMORY", "CLAUDE_CODE_SETTINGS",
              "CM_STORE_OVERRIDE", "CM_DOMAIN", "CM_CRASH_AFTER"):
        env.pop(k, None)
