# --apply runs exactly TWO orphan scans (pre-lock plan + under-lock rescan)
with _Env73() as _e_sc:
    _ctx_sc = sc.resolve_store(_e_sc.proj)
    _j_sc = cp.connect_journal(_ctx_sc)
